//! Parity with pke (https://github.com/boudinfl/pke) on fixed texts.
//!
//! `fixtures/pke_parity.rs` is generated by `fixtures/pke_parity.py`, which
//! runs pke's graph methods and records the tokens, tags and stems pke used.
//! Each method gets the same tokens here, so candidate sets must match
//! exactly, every candidate's score must agree to 1e-6, and the top 10 must
//! come in pke's order up to ties (two phrases whose pke scores differ by
//! less than 1e-9 may swap).

// Generated; regenerate rather than reformat.
#[rustfmt::skip]
#[path = "fixtures/pke_parity.rs"]
mod fixture;

use distil::text::{Document, Pos, Token};
use distil::{MultipartiteRank, PositionRank, SingleRank, TextRank, TopicRank, TopicalPageRank};
use std::collections::{HashMap, HashSet};

fn document(case: &fixture::Case) -> Document {
    Document::from_tokens(
        case.sentences
            .iter()
            .map(|s| {
                s.iter()
                    .map(|&(word, tag, stem)| Token {
                        word: word.to_string(),
                        stem: stem.to_string(),
                        pos: Some(Pos::from_upos(tag).unwrap_or(Pos::X)),
                    })
                    .collect()
            })
            .collect(),
    )
}

fn run(method: &str, case: &fixture::Case) -> Vec<(String, f64)> {
    let doc = document(case);
    let stop: HashSet<String> = case.stopwords.iter().map(|s| s.to_string()).collect();
    let all = usize::MAX;
    match method {
        "textrank" => TextRank::new().with_top_fraction(0.33).rank(&doc, all),
        "singlerank" => SingleRank::new().rank(&doc, all),
        "positionrank" => PositionRank::new().rank(&doc, all),
        "topicrank" => TopicRank::new().with_stopwords(stop).rank(&doc, all),
        "multipartiterank" => MultipartiteRank::new().with_stopwords(stop).rank(&doc, all),
        "topicalpagerank" => {
            let topics: HashMap<String, Vec<f64>> = case
                .word_topics
                .iter()
                .map(|(w, v)| (w.to_string(), v.to_vec()))
                .collect();
            TopicalPageRank::new().rank(&doc, &topics, case.doc_topics, all)
        }
        other => panic!("no distil method for {other}"),
    }
}

/// Differences between distil's ranking and pke's, empty when they agree.
fn compare(got: &[(String, f64)], want: &[(&str, f64)]) -> Vec<String> {
    let mut problems = Vec::new();
    let want_score: HashMap<&str, f64> = want.iter().copied().collect();
    let got_score: HashMap<&str, f64> = got.iter().map(|(p, s)| (p.as_str(), *s)).collect();
    let mut missing: Vec<_> = want_score
        .keys()
        .filter(|p| !got_score.contains_key(*p))
        .collect();
    let mut extra: Vec<_> = got_score
        .keys()
        .filter(|p| !want_score.contains_key(*p))
        .collect();
    missing.sort();
    extra.sort();
    if !missing.is_empty() || !extra.is_empty() {
        problems.push(format!(
            "candidates differ: missing {missing:?}, extra {extra:?}"
        ));
    }
    for (p, s) in &got_score {
        if let Some(w) = want_score.get(p) {
            if (s - w).abs() > 1e-6 {
                problems.push(format!("{p:?}: distil {s:.9}, pke {w:.9}"));
            }
        }
    }
    for (i, ((p, _), (wp, ws))) in got.iter().zip(want).take(10).enumerate() {
        match want_score.get(p.as_str()) {
            Some(s) if (s - ws).abs() < 1e-9 => {}
            _ => problems.push(format!("rank {}: distil {p:?}, pke {wp:?}", i + 1)),
        }
    }
    problems
}

#[test]
fn graph_methods_match_pke() {
    let mut failures = Vec::new();
    let mut checked = 0;
    for case in fixture::CASES {
        for (method, want) in case.methods {
            let got = run(method, case);
            assert!(!want.is_empty(), "{} {method}: empty reference", case.name);
            for p in compare(&got, want) {
                failures.push(format!("{} {method}: {p}", case.name));
            }
            checked += 1;
        }
    }
    assert_eq!(checked, 4 * 6);
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// The comparison itself must catch a swapped pair and a missing phrase.
#[test]
fn compare_detects_differences() {
    let want = [("a", 0.5), ("b", 0.3), ("c", 0.2)];
    let same: Vec<_> = want.iter().map(|(p, s)| (p.to_string(), *s)).collect();
    assert!(compare(&same, &want).is_empty());
    let swapped = vec![
        ("b".to_string(), 0.5),
        ("a".to_string(), 0.3),
        ("c".to_string(), 0.2),
    ];
    assert_eq!(compare(&swapped, &want).len(), 4);
    assert_eq!(compare(&same[..2], &want).len(), 1);
    // Tied pke scores may come in either order.
    let tied = [("a", 0.5), ("b", 0.5)];
    let flipped = vec![("b".to_string(), 0.5), ("a".to_string(), 0.5)];
    assert!(compare(&flipped, &tied).is_empty());
}
